#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in movements.log (regardless of whether its net is zero),
# plus every catalog SKU (even ones with no movements today).
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
     END {
         net["SKU-9"] += 0
         for (sku in net) print sku, net[sku]
     }' movements.log | sort > stock.txt

